import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv_transpose2d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_H 16
#define TILE_W 16
#define TH 4
#define TW 2
#define OUT_TILE_H (TILE_H * TH)
#define OUT_TILE_W (TILE_W * TW)
__global__ void conv_transpose2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const int batch_size,
    const int in_channels,
    const int out_channels,
    const int in_h,
    const int in_w,
    const int out_h,
    const int out_w,
    const int kH,
    const int kW,
    const int stride_h,
    const int stride_w,
    const int pad_h,
    const int pad_w,
    const int dilation_h,
    const int dilation_w,
    const int groups,
    const int in_channels_per_group,
    const int out_channels_per_group,
    const bool has_bias
) {
    extern __shared__ float smem_weight[];
    int bc = blockIdx.z; // combined batch * out_channels
    int oc = bc % out_channels;
    int b = bc / out_channels;
    int g = oc / out_channels_per_group;
    int oc_in_group = oc % out_channels_per_group;
    int ic_start = g * in_channels_per_group;
    int weight_size = in_channels_per_group * kH * kW;
    // Cooperative load of the weight slice for this (group, oc) into shared memory.
    // This weight slice is reused by every output pixel computed by this block,
    // avoiding redundant global memory reads across the (now larger) spatial tile.
    int tid = threadIdx.y * blockDim.x + threadIdx.x;
    int nthreads = blockDim.x * blockDim.y;
    for (int i = tid; i < weight_size; i += nthreads) {
        int kw = i % kW;
        int tmp = i / kW;
        int kh = tmp % kH;
        int ic = tmp / kH;
        int ic_global = ic_start + ic;
        int weight_idx = ((ic_global * out_channels_per_group + oc_in_group) * kH + kh) * kW + kw;
        smem_weight[i] = __ldg(&weight[weight_idx]);
    }
    __syncthreads();
    // Register blocking: each thread computes a TH x TW tile of output pixels.
    // This increases the spatial area covered per block, reducing the number
    // of blocks needed (and thus the number of redundant weight reloads from
    // global memory into shared memory across the grid) while reusing each
    // weight/input value loaded from shared/global memory across TH*TW accumulators.
    int ow[TW];
    int oh[TH];
    bool valid_w[TW];
    bool valid_h[TH];
    #pragma unroll
    for (int i = 0; i < TW; ++i) {
        ow[i] = blockIdx.x * OUT_TILE_W + threadIdx.x + i * TILE_W;
        valid_w[i] = ow[i] < out_w;
    }
    #pragma unroll
    for (int j = 0; j < TH; ++j) {
        oh[j] = blockIdx.y * OUT_TILE_H + threadIdx.y + j * TILE_H;
        valid_h[j] = oh[j] < out_h;
    }
    bool any_valid_w = false, any_valid_h = false;
    #pragma unroll
    for (int i = 0; i < TW; ++i) any_valid_w |= valid_w[i];
    #pragma unroll
    for (int j = 0; j < TH; ++j) any_valid_h |= valid_h[j];
    if (!any_valid_w || !any_valid_h) return;
    float acc[TH][TW];
    #pragma unroll
    for (int j = 0; j < TH; ++j) {
        #pragma unroll
        for (int i = 0; i < TW; ++i) acc[j][i] = 0.0f;
    }
    for (int kh = 0; kh < kH; ++kh) {
        int ih[TH];
        bool h_ok[TH];
        bool any_h_ok = false;
        #pragma unroll
        for (int j = 0; j < TH; ++j) {
            int oh_p = oh[j] + pad_h - kh * dilation_h;
            bool ok = valid_h[j] && oh_p >= 0 && (oh_p % stride_h == 0);
            int ihv = ok ? (oh_p / stride_h) : -1;
            ok = ok && ihv >= 0 && ihv < in_h;
            ih[j] = ihv;
            h_ok[j] = ok;
            any_h_ok |= ok;
        }
        if (!any_h_ok) continue;
        for (int kw = 0; kw < kW; ++kw) {
            int iw[TW];
            bool w_ok[TW];
            bool any_w_ok = false;
            #pragma unroll
            for (int i = 0; i < TW; ++i) {
                int ow_p = ow[i] + pad_w - kw * dilation_w;
                bool ok = valid_w[i] && ow_p >= 0 && (ow_p % stride_w == 0);
                int iwv = ok ? (ow_p / stride_w) : -1;
                ok = ok && iwv >= 0 && iwv < in_w;
                iw[i] = iwv;
                w_ok[i] = ok;
                any_w_ok |= ok;
            }
            if (!any_w_ok) continue;
            for (int ic = 0; ic < in_channels_per_group; ++ic) {
                int ic_global = ic_start + ic;
                float wv = smem_weight[(ic * kH + kh) * kW + kw];
                int base_idx = (b * in_channels + ic_global) * in_h;
                #pragma unroll
                for (int j = 0; j < TH; ++j) {
                    if (!h_ok[j]) continue;
                    int row_idx = (base_idx + ih[j]) * in_w;
                    #pragma unroll
                    for (int i = 0; i < TW; ++i) {
                        if (w_ok[i]) {
                            acc[j][i] += __ldg(&input[row_idx + iw[i]]) * wv;
                        }
                    }
                }
            }
        }
    }
    if (has_bias) {
        float bv = __ldg(&bias[oc]);
        #pragma unroll
        for (int j = 0; j < TH; ++j) {
            #pragma unroll
            for (int i = 0; i < TW; ++i) acc[j][i] += bv;
        }
    }
    int out_base = (b * out_channels + oc) * out_h;
    #pragma unroll
    for (int j = 0; j < TH; ++j) {
        if (!valid_h[j]) continue;
        int row_out = (out_base + oh[j]) * out_w;
        #pragma unroll
        for (int i = 0; i < TW; ++i) {
            if (valid_w[i]) {
                output[row_out + ow[i]] = acc[j][i];
            }
        }
    }
}
torch::Tensor conv_transpose2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dilation_h, int dilation_w,
    int groups,
    bool has_bias
) {
    input = input.contiguous();
    weight = weight.contiguous();
    const int batch_size = input.size(0);
    const int in_channels = input.size(1);
    const int in_h = input.size(2);
    const int in_w = input.size(3);
    const int in_channels_per_group = weight.size(0) / groups;
    const int out_channels_per_group = weight.size(1);
    const int out_channels = out_channels_per_group * groups;
    const int kH = weight.size(2);
    const int kW = weight.size(3);
    const int out_h = (in_h - 1) * stride_h - 2 * pad_h + dilation_h * (kH - 1) + 1;
    const int out_w = (in_w - 1) * stride_w - 2 * pad_w + dilation_w * (kW - 1) + 1;
    auto output = torch::empty({batch_size, out_channels, out_h, out_w}, input.options());
    const float* bias_ptr = has_bias ? bias.contiguous().data_ptr<float>() : nullptr;
    dim3 threads(TILE_W, TILE_H);
    dim3 blocks(
        (out_w + OUT_TILE_W - 1) / OUT_TILE_W,
        (out_h + OUT_TILE_H - 1) / OUT_TILE_H,
        batch_size * out_channels
    );
    size_t shared_mem_size = static_cast<size_t>(in_channels_per_group) * kH * kW * sizeof(float);
    conv_transpose2d_kernel<<<blocks, threads, shared_mem_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        in_h,
        in_w,
        out_h,
        out_w,
        kH,
        kW,
        stride_h,
        stride_w,
        pad_h,
        pad_w,
        dilation_h,
        dilation_w,
        groups,
        in_channels_per_group,
        out_channels_per_group,
        has_bias
    );
    return output;
}
"""

conv_transpose2d_cpp_source = r"""
torch::Tensor conv_transpose2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dilation_h, int dilation_w,
    int groups,
    bool has_bias
