"""

conv_transpose2d_ext = load_inline(
    name="conv_transpose2d_ext",
    cpp_sources=conv_transpose2d_cpp_source,
    cuda_sources=conv_transpose2d_source,
    functions=["conv_transpose2d_cuda"],
    verbose=False,
